static final double GBS_ARM = 0.0000133334, REQ = 0.20 / 1_000_000;

static double lambda(double reqPerMonth, double seconds, double gb) {
    return reqPerMonth * REQ + reqPerMonth * seconds * gb * GBS_ARM;
}

public static void main(String[] args) {
    double catalog = 300.0 * 86_400 * 30;
    System.out.printf("%.0f USD%n", lambda(catalog, 0.08, 1));
}
